-- Every date/actor here is synthetic and confined to rtn_freshness_lab_ci.
SET ROLE postgres;
SELECT lab.check('freshness: old attempt bytes untouched',(SELECT to_jsonb(t)=lab.ctx('old_attempt')FROM rtn_private.attempts t WHERE id=(lab.ctx('old_start')->>'attempt_id')::uuid));
SELECT lab.check('freshness: old keys receive only unknown metadata defaults',(SELECT to_jsonb(k)-'normative_limits'-'normative_cutoff_at'-'editorial_review_before'=lab.ctx('old_key') AND k.normative_cutoff_at IS NULL AND k.editorial_review_before IS NULL AND k.normative_limits='[]'FROM rtn_private.key_sets k WHERE id=(lab.ctx('old_review')->>'key_set_id')::uuid));
SELECT lab.check('freshness: old release and unrelated guards untouched',(SELECT to_jsonb(r)=lab.ctx('old_release_row')FROM rtn_private.releases r WHERE id=(lab.ctx('old_release')->>'release_id')::uuid)AND lab.ctx('unrelated_proc')=(SELECT jsonb_agg(to_jsonb(p)ORDER BY p.oid)FROM pg_proc p WHERE p.oid IN('public.submit_rtn_attempt(uuid,jsonb)'::regprocedure,'public.get_rtn_attempt(uuid)'::regprocedure,'public.account_deletion_erase_data(uuid,text)'::regprocedure,'rtn_private.reject_mutation()'::regprocedure,'rtn_private.freeze_attempt()'::regprocedure)));
SELECT lab.check('freshness: metadata helpers remain private',NOT has_function_privilege('authenticated','rtn_private.normative_bounds(jsonb,jsonb)','EXECUTE') AND NOT has_function_privilege('service_role','rtn_private.assert_bank_normative_current(uuid,timestamptz)','EXECUTE'));
SELECT lab.keep('bounds',rtn_private.normative_bounds('{"review_before":"2030-03-01"}','[{"normative_valid_until":"2032-09-01","evidence":[{"url":"https://pravo.gov.ru/test","validity_basis":{"valid_until":"2029-01-01"}}]}]'));
SELECT lab.check('freshness: recursive aliases use earliest exclusive Moscow midnight',(lab.ctx('bounds')->>'cutoff_at')::timestamptz='2028-12-31 21:00:00+00'::timestamptz AND jsonb_array_length(lab.ctx('bounds')->'limits')=3 AND EXISTS(SELECT 1 FROM jsonb_array_elements(lab.ctx('bounds')->'limits')x WHERE x->>'kind'='editorial_review' AND x->>'exclusive'='true'));
SELECT lab.denied('freshness: malformed calendar date rejected','SELECT rtn_private.normative_bounds(''{"review_before":"2027-02-29"}'',''[]'')','22023');
SELECT lab.denied('freshness: explicit unknown date rejected','SELECT rtn_private.normative_bounds(''{"review_before":null}'',''[]'')','22023');
SET TIME ZONE 'Pacific/Auckland';
SELECT lab.check('freshness: server session timezone cannot change date boundary',(rtn_private.normative_bounds('{"review_before":"2030-03-01"}','[]')->>'cutoff_at')::timestamptz='2030-02-28 21:00:00+00'::timestamptz);
RESET TIME ZONE;
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.role','authenticated',false);
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000101',false);
SELECT lab.check('freshness: old active attempt resumes despite unknown review deadline',public.start_rtn_attempt((lab.ctx('assignment_id')#>>'{}')::uuid)->>'attempt_id'=lab.ctx('old_start')->>'attempt_id');
SELECT lab.check('freshness: learner sees admission status while preserving active result link',NOT(public.get_rtn_student_workspace()->'assignments'->0->>'can_start')::boolean AND public.get_rtn_student_workspace()->'assignments'->0->>'normative_status'='review_required' AND public.get_rtn_student_workspace()->'assignments'->0->>'last_attempt_status'='active');
SELECT lab.keep('old_submitted',public.submit_rtn_attempt((lab.ctx('old_start')->>'attempt_id')::uuid,'{"q1":["a"],"q2":["yes"]}'));
SELECT lab.check('freshness: old active snapshot grades and stays readable',(lab.ctx('old_submitted')->>'passed')::boolean AND public.get_rtn_attempt((lab.ctx('old_start')->>'attempt_id')::uuid)->>'status'='submitted');
SELECT lab.denied('freshness: no new attempt without declared review deadline',format('SELECT public.start_rtn_attempt(%L)',lab.ctx('assignment_id')#>>'{}'),'22023');
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000001',false);
SELECT lab.keep('old_workspace',public.get_rtn_workspace('11111111-1111-4111-8111-111111111111'));
SELECT lab.check('freshness: released old bank is not misrepresented as fresh',lab.ctx('old_workspace')->'banks'->0->>'key_status'='released' AND lab.ctx('old_workspace')->'banks'->0->>'normative_status'='review_required' AND NOT(lab.ctx('old_workspace')->'banks'->0->>'available_for_training')::boolean);
SELECT lab.denied('freshness: explicit reassignment also requires current review',format('SELECT public.assign_rtn_training(''11111111-1111-4111-8111-111111111111'',%L,ARRAY[''71000000-0000-4000-8000-000000000101'']::uuid[])',lab.ctx('bank_id')#>>'{}'),'22023');
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000999',false);
SELECT lab.check('freshness: published old receipt remains idempotently readable',(public.publish_rtn_release((lab.ctx('old_review')->>'key_set_id')::uuid,(now()AT TIME ZONE'Europe/Moscow')::date-2,'Synthetic historical released version')->>'replayed')::boolean);
SELECT lab.keep('legal_only_review',public.review_rtn_keys((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('bank_revision_id')#>>'{}')::uuid,lab.ctx('keys'),'Synthetic legal validity without weekly review',jsonb_set(lab.ctx('module'),'{valid_until}','"2032-09-01"')));
SELECT lab.denied('freshness: legal 2032 validity cannot replace mandatory weekly review',format('SELECT public.publish_rtn_release(%L,%L,''Synthetic legal-only publication denied'')',lab.ctx('legal_only_review')->>'key_set_id',(now()AT TIME ZONE'Europe/Moscow')::date),'22023');
SELECT lab.keep('evidence_only_review',public.review_rtn_keys((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('bank_revision_id')#>>'{}')::uuid,jsonb_set(lab.ctx('keys'),'{0,evidence,0,review_before}',to_jsonb(((now()AT TIME ZONE'Europe/Moscow')::date+3)::text)),'Synthetic nested evidence date without module review',lab.ctx('module')));
SELECT lab.denied('freshness: nested evidence review date cannot replace top level editorial date',format('SELECT public.publish_rtn_release(%L,%L,''Synthetic nested review bypass denied'')',lab.ctx('evidence_only_review')->>'key_set_id',(now()AT TIME ZONE'Europe/Moscow')::date),'22023');
SELECT lab.denied('freshness: editorial deadline cannot exceed seven days from actual review',format('SELECT public.review_rtn_keys(%L,%L,%L,''Synthetic excessive editorial window'',%L)',lab.ctx('bank_id')#>>'{}',lab.ctx('bank_revision_id')#>>'{}',lab.ctx('keys'),jsonb_set(lab.ctx('module'),'{review_before}',to_jsonb(((now()AT TIME ZONE'Europe/Moscow')::date+8)::text))),'22023');
SELECT lab.keep('module_fresh',jsonb_set(lab.ctx('module'),'{review_before}',to_jsonb(((now()AT TIME ZONE'Europe/Moscow')::date+3)::text)));
SELECT lab.keep('fresh_review',public.review_rtn_keys((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('bank_revision_id')#>>'{}')::uuid,lab.ctx('keys'),'Synthetic explicit weekly editorial review',lab.ctx('module_fresh')));
SELECT lab.check('freshness: exact review retry is idempotent',(public.review_rtn_keys((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('bank_revision_id')#>>'{}')::uuid,lab.ctx('keys'),'Synthetic explicit weekly editorial review',lab.ctx('module_fresh'))->>'key_set_id')=lab.ctx('fresh_review')->>'key_set_id');
SELECT lab.keep('changed_deadline',public.review_rtn_keys((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('bank_revision_id')#>>'{}')::uuid,lab.ctx('keys'),'Synthetic explicit weekly editorial review',jsonb_set(lab.ctx('module_fresh'),'{review_before}',to_jsonb(((now()AT TIME ZONE'Europe/Moscow')::date+4)::text))));
SELECT lab.check('freshness: same answers materials with a different deadline is a new immutable review',lab.ctx('changed_deadline')->>'key_set_id'<>lab.ctx('fresh_review')->>'key_set_id');
SELECT lab.denied('freshness: publication effective at exclusive cutoff is refused',format('SELECT public.publish_rtn_release(%L,%L,''Synthetic future activation too late'')',lab.ctx('fresh_review')->>'key_set_id',(now()AT TIME ZONE'Europe/Moscow')::date+3),'22023');
SELECT lab.keep('fresh_release',public.publish_rtn_release((lab.ctx('fresh_review')->>'key_set_id')::uuid,(now()AT TIME ZONE'Europe/Moscow')::date-1,'Synthetic currently reviewed version'));
SET ROLE postgres;
SELECT lab.keep('cutoff',to_jsonb((SELECT normative_cutoff_at FROM rtn_private.key_sets WHERE id=(lab.ctx('fresh_review')->>'key_set_id')::uuid)));
SELECT lab.check('freshness: instant immediately before cutoff admitted and exact cutoff refused',rtn_private.normative_current((lab.ctx('fresh_review')->>'key_set_id')::uuid,(lab.ctx('cutoff')#>>'{}')::timestamptz-interval '1 microsecond') AND NOT rtn_private.normative_current((lab.ctx('fresh_review')->>'key_set_id')::uuid,(lab.ctx('cutoff')#>>'{}')::timestamptz));
SELECT lab.denied('freshness: immutable deadline cannot be extended in place','UPDATE rtn_private.key_sets SET normative_cutoff_at=now()+interval ''1 year''');
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.role','authenticated',false);
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000101',false);
SELECT lab.keep('fresh_start',public.start_rtn_attempt((lab.ctx('assignment_id')#>>'{}')::uuid));
SELECT lab.check('freshness: new attempt uses the reviewed release',lab.ctx('fresh_start')->>'release_id'=lab.ctx('fresh_release')->>'release_id' AND public.get_rtn_assignment((lab.ctx('assignment_id')#>>'{}')::uuid)->'assignment'->>'normative_status'='current');
SET ROLE postgres;
SELECT lab.keep('fresh_attempt_snapshot',(SELECT to_jsonb(t)FROM rtn_private.attempts t WHERE id=(lab.ctx('fresh_start')->>'attempt_id')::uuid));
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000999',false);
SELECT lab.keep('expired_review',public.review_rtn_keys((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('bank_revision_id')#>>'{}')::uuid,lab.ctx('keys'),'Synthetic historical expired review',jsonb_set(lab.ctx('module'),'{review_before}',to_jsonb(((now()AT TIME ZONE'Europe/Moscow')::date-1)::text))));
SELECT lab.denied('freshness: expired reviewed package cannot be newly published',format('SELECT public.publish_rtn_release(%L,%L,''Synthetic rejected expired publication'')',lab.ctx('expired_review')->>'key_set_id',(now()AT TIME ZONE'Europe/Moscow')::date),'22023');
SET ROLE postgres;
-- Simulate passage of time after a genuine historical publication. This
-- owner-only fixture INSERT is not a product publishing bypass or migration.
INSERT INTO rtn_private.releases(bank_id,key_set_id,effective_from,release_note,published_by,published_at)
 VALUES((lab.ctx('bank_id')#>>'{}')::uuid,(lab.ctx('expired_review')->>'key_set_id')::uuid,(now()AT TIME ZONE'Europe/Moscow')::date,'Synthetic already-published historical expiry','81000000-0000-4000-8000-000000000999',now()-interval '1 hour');
SELECT lab.check('freshness: fixture proves an older still-fresh edition exists',rtn_private.normative_current((lab.ctx('fresh_review')->>'key_set_id')::uuid,clock_timestamp()));
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000101',false);
SELECT lab.check('freshness: active attempt remains frozen across later expired edition',public.start_rtn_attempt((lab.ctx('assignment_id')#>>'{}')::uuid)->>'attempt_id'=lab.ctx('fresh_start')->>'attempt_id');
SELECT lab.check('freshness: latest expired edition disables new starts without hiding active attempt',NOT(public.get_rtn_student_workspace()->'assignments'->0->>'can_start')::boolean AND public.get_rtn_student_workspace()->'assignments'->0->>'last_attempt_status'='active' AND public.get_rtn_assignment((lab.ctx('assignment_id')#>>'{}')::uuid)->'assignment'->>'normative_status'='review_required');
SET ROLE postgres;
SELECT lab.check('freshness: active frozen snapshot still byte identical',(SELECT to_jsonb(t)=lab.ctx('fresh_attempt_snapshot')FROM rtn_private.attempts t WHERE id=(lab.ctx('fresh_start')->>'attempt_id')::uuid));
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000101',false);
SELECT public.submit_rtn_attempt((lab.ctx('fresh_start')->>'attempt_id')::uuid,'{"q1":["a"],"q2":["yes"]}');
SELECT lab.denied('freshness: no fallback to older fresh edition when latest expired',format('SELECT public.start_rtn_attempt(%L)',lab.ctx('assignment_id')#>>'{}'),'22023');
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000001',false);
SELECT lab.keep('precheck_workspace',public.get_rtn_workspace('11111111-1111-4111-8111-111111111111'));
SELECT lab.check('freshness: organization is told review required for latest edition',lab.ctx('precheck_workspace')->'banks'->0->>'normative_status'='review_required' AND NOT(lab.ctx('precheck_workspace')->'banks'->0->>'available_for_training')::boolean);
SET ROLE postgres;
-- Simulate the bounded manual-check cooldown elapsing without a wallclock nap.
UPDATE rtn_private.check_runs SET queued_at=now()-interval '3 minutes';
SET ROLE authenticated;
SELECT lab.keep('manual',public.request_rtn_source_check('11111111-1111-4111-8111-111111111111',(lab.ctx('source')->>'source_id')::uuid));
SET ROLE service_role;
SELECT set_config('request.jwt.claim.role','service_role',false);
SELECT lab.keep('unchanged_claim',public.claim_rtn_check((lab.ctx('manual')->>'run_id')::uuid));
SELECT public.complete_rtn_check((lab.ctx('unchanged_claim')->>'run_id')::uuid,(lab.ctx('unchanged_claim')->>'lease_token')::uuid,jsonb_build_object('status','unchanged','sha256',repeat('a',64),'original_path',(lab.ctx('source')->>'source_id')||'/'||repeat('a',64)||'.pdf','media_type','application/pdf','byte_size',1234,'document_url','https://www.gosnadzor.ru/service/list/normative-lab/a1.pdf','metadata',jsonb_build_object('source_page_url','https://www.gosnadzor.ru/service/list/normative-lab/','observations',jsonb_build_array(jsonb_build_object('kind','weekly-check','sha256',repeat('a',64))))));
SET ROLE postgres;
SELECT lab.check('freshness: unchanged source check cannot extend normative deadline',(SELECT normative_cutoff_at=(lab.ctx('cutoff')#>>'{}')::timestamptz FROM rtn_private.key_sets WHERE id=(lab.ctx('fresh_review')->>'key_set_id')::uuid));
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.role','authenticated',false);
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000001',false);
SELECT lab.check('freshness: successful byte check leaves expired newest edition blocked',NOT(public.get_rtn_workspace('11111111-1111-4111-8111-111111111111')->'banks'->0->>'available_for_training')::boolean);
SELECT lab.denied('freshness: current quota entitlement does not bypass expired keys',format('SELECT public.assign_rtn_training(''11111111-1111-4111-8111-111111111111'',%L,ARRAY[''71000000-0000-4000-8000-000000000101'']::uuid[])',lab.ctx('bank_id')#>>'{}'),'22023');
SELECT set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000102',false);
SELECT lab.denied('freshness: foreign tenant cannot inspect assigned materials',format('SELECT public.get_rtn_assignment(%L)',lab.ctx('assignment_id')#>>'{}'));
SET ROLE postgres;
SELECT lab.check('freshness: unrelated client courses results finances preserved',lab.ctx('old_data')=(SELECT jsonb_build_array((SELECT jsonb_agg(x)FROM public.courses x),(SELECT jsonb_agg(x)FROM public.test_attempts x),(SELECT jsonb_agg(x)FROM public.subscription_invoices x))));
